private static String clean(String raw) {
    return Normalizer.normalize(raw.strip(), Normalizer.Form.NFC);
}

void importCustomers(Path csv, long agencyId) throws IOException {
    for (String line : Files.readAllLines(csv, StandardCharsets.UTF_8)) {
        String[] cols = line.split(",");
        customerRepository.save(new Customer(agencyId, clean(cols[0]), clean(cols[1])));
    }
}

@GetMapping("/customers")
List<CustomerDto> search(@RequestParam String name) {
    return customerRepository.findByFullName(clean(name)).stream()
            .map(CustomerDto::from)
            .toList();
}

